const req = $('Validate Slots Request').first().json;
const ANY = ['', 'any', 'no preference', 'none', 'no', 'sem preferencia'];
const isAny = ANY.includes(norm(req.barber));

const services = readServices($input.all());
const service = services.find(s => norm(s.name) === norm(req.service));
const stop = response => [{ json: { _stop: true, _response: response } }];
if (req.service && !service) return stop({ status: 'service_not_found', message: 'Serviço não encontrado.' });
const duration = service ? service.duration : RULES.defaultDuration;

const all = readBarbers($('Read Barbers for Slots').all());
const chosen = isAny ? all : all.filter(b => norm(b.barber) === norm(req.barber));
if (!chosen.length) return stop({ status: 'barber_not_found', message: 'Barbeiro não encontrado.' });

const working = chosen.filter(b => b.days.includes(req.weekday));
if (!working.length) {
  return stop({ status: 'ok', date: req.date, barber: isAny ? 'any' : chosen[0].barber, duration, dayOff: true, slots: [] });
}
return working.map(b => ({ json: { ...b, isAny, duration, _stop: false } }));

const req = $('Validate Slots Request').first().json;
const step = req.rules.step;
const SHOP_TZ = req.timezone || 'America/Sao_Paulo';
const barbers = $('Select Barbers for Day').all().map(i => i.json);
const isAny = barbers[0].isAny;
const duration = barbers[0].duration;
const calSet = new Set(barbers.map(b => b.calendarId));

const busy = {};
const failed = new Set();

let allItems = [];
try {
  allItems = $('Label Event Source').all();
} catch (e) {
  allItems = [];
}

for (const it of allItems) {
  const ev = it.json || {};
  const cal = String(ev.sourceCalendarId || '').trim();
  if (!calSet.has(cal)) continue;
  if (ev.error) { failed.add(cal); continue; }
  if (!ev.start) continue;
  if (String(ev.status || '').toLowerCase() === 'cancelled') continue;
  if (Array.isArray(ev.attendees) && ev.attendees.some(a => a && a.self === true && String(a.responseStatus || '').toLowerCase() === 'declined')) continue;

  const allDay = !ev.start.dateTime;
  const s = allDay ? DateTime.fromISO(ev.start.date, { zone: SHOP_TZ }) : DateTime.fromISO(ev.start.dateTime);
  const endRaw = ev.end ? (ev.end.dateTime || ev.end.date) : null;
  const e = allDay ? DateTime.fromISO(endRaw || ev.start.date, { zone: SHOP_TZ }) : DateTime.fromISO(endRaw || ev.start.dateTime);
  if (!s.isValid || !e.isValid) continue;
  (busy[cal] = busy[cal] || []).push({ start: s.toMillis(), end: Math.max(e.toMillis(), s.toMillis()) });
}

const readable = barbers.filter(b => !failed.has(b.calendarId));
if (!readable.length) {
  return [{ json: { status: 'system_error', message: 'Não foi possível acessar a agenda do Google. Verifique a credencial.' } }];
}

const day = DateTime.fromISO(req.date, { zone: SHOP_TZ });
const nowMs = Date.now();
const first = Math.min(...readable.map(b => b.start));
const last = Math.max(...readable.map(b => b.end));
const slots = [];

for (let m = first; m + duration <= last; m += step) {
  const s = day.set({ hour: Math.floor(m / 60), minute: m % 60, second: 0, millisecond: 0 });
  const e = s.plus({ minutes: duration });
  if (s.toMillis() < nowMs) continue;
  const free = readable
    .filter(b => m >= b.start && m + duration <= b.end)
    .filter(b => !(busy[b.calendarId] || []).some(x => s.toMillis() < x.end && e.toMillis() > x.start))
    .map(b => b.barber);
  if (free.length) {
    slots.push({
      startTime: s.toISO({ suppressMilliseconds: true }),
      endTime: e.toISO({ suppressMilliseconds: true }),
      label: s.toFormat('HH:mm'),
      barbers: free,
    });
  }
}

return [{ json: {
  status: 'ok',
  date: req.date,
  barber: isAny ? 'any' : barbers[0].barber,
  timezone: SHOP_TZ,
  duration,
  calendarReadStatus: readable.length === barbers.length ? 'ok' : 'partial',
  slots,
} }];

const body = $('Book Appointment Webhook').first().json.body || {};
const norm = v => String(v ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ');
const rows = $input.all().map(i => i.json);

const found = rows.find(r => norm(r.barber || r.Barber || r.barbeiro || r.nome || r.name) === norm(body.barber)) || rows[0] || {};
const calendarId = String(found.calendarId || found.CalendarId || found.email || found.Email || 'primary').trim();
const barberName = found.barber || found.Barber || found.barbeiro || found.nome || body.barber || 'Barbeiro';
const clientName = body.name || String(body.summary || '').split('-')[1]?.trim() || 'Cliente';

return [{
  json: {
    calendarId,
    barber: barberName,
    name: clientName,
    service: body.service || 'Corte',
    startTime: body.startTime,
    endTime: body.endTime,
    summary: body.summary || 'Corte Barbearia',
    description: body.description || '',
    number: String(body.number || body.phone_number || '')
  }
}];

const booking = $('Prepare Booking Event').first().json || {};
const calendarRes = $('Create Appointment in Calendar').first().json || {};

return [{
  json: {
    status: 'booked',
    barber: booking.barber,
    name: booking.name,
    service: booking.service,
    startTime: booking.startTime,
    endTime: booking.endTime,
    summary: booking.summary,
    number: booking.number,
    calendarId: booking.calendarId,
    eventId: calendarRes.id || 'ok'
  }
}];

const raw = $('Agent Chat Webhook').first().json || {};
const body = raw.body || raw;
const message = String(body.message || raw.message || 'Olá').trim();
const sessionId = String(body.sessionId || raw.sessionId || 'default');

const norm = v => String(v ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const isActive = v => !['nao', 'n', 'false', '0', 'inativo'].includes(norm(v));

function getBarberName(r) {
  if (!r || typeof r !== 'object') return '';
  return String(r.barber || r.Barber || r.barbeiro || r.Barbeiro || r.nome || r.Nome || r.name || r.Name || r.profissional || '').trim();
}

function getServiceName(r) {
  if (!r || typeof r !== 'object') return '';
  return String(r.servico || r.Servico || r.service || r.Service || r.nome || r.Nome || '').trim();
}

function getPrice(r) {
  return r.preco !== undefined ? r.preco : (r.Preco !== undefined ? r.Preco : (r.price || '35,00'));
}

function getDuration(r) {
  return r.duracao !== undefined ? r.duracao : (r.Duracao !== undefined ? r.Duracao : (r.duration || '30'));
}

function getAtivo(r) {
  return r.ativo !== undefined ? r.ativo : (r.Ativo !== undefined ? r.Ativo : 'sim');
}

function parseTime(v, fallback) {
  if (v === undefined || v === null || String(v).trim() === '') return parseTime(fallback);
  if (typeof v === 'number') return v < 1 ? Math.round(v * 1440) : Math.round(v * 60);
  const m = String(v).trim().match(/^(\d{1,2})(?:[:h](\d{2})?)?/i);
  return m ? Number(m[1]) * 60 + Number(m[2] || 0) : parseTime(fallback);
}

const hhmm = min => String(Math.floor(min / 60)).padStart(2, '0') + ':' + String(min % 60).padStart(2, '0');

function generateBarberSlots(startMin, endMin) {
  const slots = [];
  for (let m = startMin; m + 30 <= endMin; m += 90) {
    slots.push(hhmm(m));
  }
  if (slots.length < 3) {
    for (let m = startMin; m + 30 <= endMin; m += 60) {
      if (!slots.includes(hhmm(m))) slots.push(hhmm(m));
    }
  }
  return slots.sort().slice(0, 5);
}

// 1. Lê e deduplica os barbeiros da aba barbers
let barbersRows = [];
const barberNodeCandidates = ['Read Barbers Sheet1', 'Read Barbers for Chat', 'Read Barbers Sheet'];
for (const nodeName of barberNodeCandidates) {
  try {
    const items = $(nodeName).all();
    if (items && items.length > 0) {
      const valid = items.map(i => i.json).filter(r => r && !r.error && !r.errorMessage && getBarberName(r));
      if (valid.length > 0) {
        barbersRows = valid;
        break;
      }
    }
  } catch (e) {}
}

const seenBarbers = new Set();
const activeBarbers = [];
for (const r of barbersRows) {
  const name = getBarberName(r);
  if (!name || !isActive(getAtivo(r)) || seenBarbers.has(norm(name))) continue;
  seenBarbers.add(norm(name));
  const dias = String(r.dias || r.Dias || 'seg-sex').trim();
  const inicio = parseTime(r.inicio || r.Inicio, '09:00');
  const fim = parseTime(r.fim || r.Fim, '18:00');
  activeBarbers.push({
    name,
    dias,
    inicioStr: hhmm(inicio),
    fimStr: hhmm(fim),
    slots: generateBarberSlots(inicio, fim)
  });
}

// 2. Lê e deduplica os serviços da aba servicos (evita repetição quando há múltiplos barbeiros antes)
let servicesRows = [];
const serviceNodeCandidates = ['Read Services Sheet1', 'Read Services for Chat', 'Read Services Sheet'];
for (const nodeName of serviceNodeCandidates) {
  try {
    const items = $(nodeName).all();
    if (items && items.length > 0) {
      const valid = items.map(i => i.json).filter(r => r && !r.error && !r.errorMessage && getServiceName(r));
      if (valid.length > 0) {
        servicesRows = valid;
        break;
      }
    }
  } catch (e) {}
}

const seenServices = new Set();
const activeServices = [];
for (const r of servicesRows) {
  const name = getServiceName(r);
  if (!name || !isActive(getAtivo(r)) || seenServices.has(norm(name))) continue;
  seenServices.add(norm(name));
  activeServices.push({
    name,
    price: getPrice(r),
    duration: getDuration(r)
  });
}

// 3. Monta as listas formatadas
const servicesListText = activeServices.length > 0 
  ? activeServices.map((s, idx) => `[${idx + 1}] *${s.name}* — R$ ${s.price} (${s.duration} min)`).join('\n')
  : `[1] *Corte Simples* — R$ 35,00 (30 min)\n[2] *Barba Terapia* — R$ 30,00 (30 min)\n[3] *Corte + Barba* — R$ 60,00 (60 min)`;

const barbersListText = activeBarbers.length > 0
  ? activeBarbers.map((b, idx) => `[${idx + 1}] *${b.name}* (Atende ${b.dias}, ${b.inicioStr} às ${b.fimStr})`).join('\n') + `\n[${activeBarbers.length + 1}] *Sem preferência* (Primeiro disponível)`
  : `[1] *Barbeiro da Casa* (Atende seg-sex, 09:00 às 18:00)\n[2] *Sem preferência* (Primeiro disponível)`;

// 4. Monta a grade de horários individual de cada barbeiro da planilha
const barberSchedulesText = activeBarbers.length > 0
  ? activeBarbers.map(b => {
      const slotsFormatted = b.slots.map((s, i) => `[${i + 1}] *${s}*`).join(' | ');
      return `• Barbeiro ${b.name} (Expediente ${b.inicioStr} às ${b.fimStr}):\n${slotsFormatted}`;
    }).join('\n\n')
  : '• Horários: [1] *09:00* | [2] *10:30* | [3] *14:00* | [4] *15:30* | [5] *17:00*';

return [{
  json: {
    message,
    chatInput: message,
    prompt: message,
    sessionId,
    servicesListText,
    barbersListText,
    barberSchedulesText
  }
}];

const aiRaw = $json.text || $json.output || $json.response || '';
let reply = (typeof aiRaw === 'string' && aiRaw.trim().length > 10) ? aiRaw.trim() : '';

// Fallback inteligente caso o Gemini não responda
if (!reply) {
  let inputMsg = '';
  try {
    inputMsg = String($('Format Agent Input').first().json.message || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  } catch (e) {
    inputMsg = '';
  }

  const servicesText = $('Format Agent Input').first().json.servicesListText || '';
  const barbersText = $('Format Agent Input').first().json.barbersListText || '';
  const schedulesText = $('Format Agent Input').first().json.barberSchedulesText || '';

  // Verifica intenções específicas antes de termos genéricos (evita repetir serviços quando pede barbeiros)
  if (inputMsg.includes('liste os barbeiros') || inputMsg.includes('ver os profissionais') || inputMsg.includes('profissionais disponiveis')) {
    reply = `Ótima escolha! 💈\n\nAgora escolha o profissional que irá te atender:\n\n${barbersText}\n\nDigite o *número do barbeiro*:`;
  } else if (inputMsg.includes('liste os horarios') || inputMsg.includes('horarios disponiveis')) {
    reply = `Perfeito! Barbeiro selecionado. 🧔\nConsultei a agenda para amanhã:\n\n${schedulesText}\n\nDigite o *número do horário* que você prefere:`;
  } else if (inputMsg === '1' || inputMsg.includes('ver os servicos') || inputMsg.includes('servico') || inputMsg.includes('preco')) {
    reply = `✂️ *Nossos Serviços:*\n\n${servicesText}\n\nDigite o *número do serviço* que você deseja agendar:`;
  } else if (inputMsg === '2' || inputMsg.includes('barbeiro')) {
    reply = `Agora escolha o profissional que irá te atender:\n\n${barbersText}\n\nDigite o *número do barbeiro*:`;
  } else if (inputMsg.includes('visagismo')) {
    reply = 'Chegue com 5 a 10 minutos de antecedência para relaxar com um café espresso cortesia e evite lavar o cabelo com água muito quente antes do atendimento.';
  } else if (inputMsg.match(/(10:30|14:00|16:30|17:30|08:00|09:00|[1-5])/)) {
    reply = 'Excelente escolha! ⏰\n\nPara concluirmos sua reserva na agenda, por favor digite seu *Nome completo*:';
  } else {
    reply = 'Olá! Seja bem-vindo à *Barbearia Imperial*. 💈\n\nDigite o número da opção desejada:\n[1] Consultar nossos serviços e tabela de preços\n[2] Ver os horários disponíveis com nossos barbeiros\n[3] Realizar ou confirmar seu agendamento';
  }
}

return [{
  json: {
    status: 'ok',
    response: reply
  }
}];
